  if (next >= maxAllowed) {
    window.ebdAskSubscribe("Liberar Todos os 20 Desafios de Quem Sou Eu na Bíblia!");
    window.EBD_STATE.whoAmIIdx = 0;
  } else {
    window.EBD_STATE.whoAmIIdx = next;
  }
